window.officeBundle = {"date":"2026-11-18","services":{"morning_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"The Lord is in his holy temple; let all the earth keep silence before him."},{"line_type":"citation","content":"HABAKKUK 2:20"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Let us humbly confess our sins to Almighty God."},{"line_type":"rubric","content":"Silence is kept. All kneeling, the Officiant and People say"},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Venite"},{"line_type":"subheading","content":"O Come"},{"line_type":"rubric","content":"Officiant and People, all standing"},{"line_type":"leader","content":"The mercy of the Lord is everlasting:"},{"line_type":"congregation","content":"O come, let us adore him."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"O come, let us sing unto the Lord; *"},{"line_type":"congregation","content":"let us heartily rejoice in the strength of our salvation."},{"line_type":"congregation","content":"Let us come before his presence with thanksgiving *"},{"line_type":"congregation","content":"and show ourselves glad in him with psalms."},{"line_type":"congregation","content":"For the Lord is a great God *"},{"line_type":"congregation","content":"and a great King above all gods."},{"line_type":"congregation","content":"In his hand are all the depths of the earth, *"},{"line_type":"congregation","content":"and the heights of the hills are his also."},{"line_type":"congregation","content":"The sea is his, for he made it, *"},{"line_type":"congregation","content":"and his hands prepared the dry land."},{"line_type":"congregation","content":"O come, let us worship and fall down, *"},{"line_type":"congregation","content":"and kneel before the Lord our Maker."},{"line_type":"congregation","content":"For he is our God, *"},{"line_type":"congregation","content":"and we are the people of his pasture,"},{"line_type":"congregation","content":"and the sheep of his hand."},{"line_type":"rubric","content":"The following verses may be omitted."},{"line_type":"congregation","content":"Today, if you will hear his voice, harden not your hearts *"},{"line_type":"congregation","content":"as in the provocation, and as in the day of temptation in the wilderness,"},{"line_type":"congregation","content":"When your fathers tested me, *"},{"line_type":"congregation","content":"and put me to the proof, though they had seen my works."},{"line_type":"congregation","content":"Forty years long was I grieved with this generation and said, *"},{"line_type":"congregation","content":"\u201cIt is a people that err in their hearts, for they have not known my ways,\u201d"},{"line_type":"congregation","content":"Of whom I swore in my wrath *"},{"line_type":"congregation","content":"that they should not enter into my rest."},{"line_type":"citation","content":"Psalm 95:1-7, 8-11"},{"line_type":"leader","content":"The mercy of the Lord is everlasting:"},{"line_type":"congregation","content":"O come, let us adore him."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 47"},{"line_type":"subheading","content":"Omnes gentes, plaudite"},{"line_type":"leader","content":"O clap your hands together, all you peoples; *","preface":1},{"line_type":"leader","content":"O cry aloud unto God with shouts of joy."},{"line_type":"congregation","content":"For the L\u1d0f\u0280\u1d05 Most High is to be feared; *","preface":2},{"line_type":"congregation","content":"he is the great King over all the earth."},{"line_type":"leader","content":"He shall subdue the peoples under us, *","preface":3},{"line_type":"leader","content":"and the nations under our feet."},{"line_type":"congregation","content":"He shall choose our inheritance for us, *","preface":4},{"line_type":"congregation","content":"the pride of Jacob whom he loved."},{"line_type":"leader","content":"God has gone up with a shout of triumph, *","preface":5},{"line_type":"leader","content":"the L\u1d0f\u0280\u1d05 with the sound of the trumpet."},{"line_type":"congregation","content":"O sing praises, sing praises unto our God; *","preface":6},{"line_type":"congregation","content":"O sing praises, sing praises unto our King."},{"line_type":"leader","content":"For God is the King of all the earth; *","preface":7},{"line_type":"leader","content":"think upon his mighty acts and praise him with a song."},{"line_type":"congregation","content":"God reigns over the nations; *","preface":8},{"line_type":"congregation","content":"God sits on his holy throne."},{"line_type":"leader","content":"The princes of the peoples are gathered with the people of the God of Abraham; *","preface":9},{"line_type":"leader","content":"for the mighty upon earth have become the servants of the Lord, and he is very highly exalted."},{"line_type":"heading","content":"Psalm 48"},{"line_type":"subheading","content":"Magnus Dominus"},{"line_type":"leader","content":"Great is the L\u1d0f\u0280\u1d05 and highly to be praised *","preface":1},{"line_type":"leader","content":"in the city of our God, even upon his holy hill."},{"line_type":"congregation","content":"The hill of Zion is beautiful and lofty; *","preface":2},{"line_type":"congregation","content":"it is the joy of the whole earth."},{"line_type":"leader","content":"Upon the north side lies the city of the great King; *","preface":3},{"line_type":"leader","content":"God is well known in her palaces as a sure refuge."},{"line_type":"congregation","content":"For behold, the kings of the earth *","preface":4},{"line_type":"congregation","content":"have gathered and advanced together."},{"line_type":"leader","content":"They marvelled to see such things; *","preface":5},{"line_type":"leader","content":"they were astonished and fled in terror."},{"line_type":"congregation","content":"Trembling came upon them, and anguish, *","preface":6},{"line_type":"congregation","content":"as upon a woman in travail."},{"line_type":"leader","content":"You caused the east wind to blow *","preface":7},{"line_type":"leader","content":"and broke apart the ships of Tarshish."},{"line_type":"congregation","content":"As we have heard, so have we seen in the city of the L\u1d0f\u0280\u1d05 of hosts, in the city of our God; *","preface":8},{"line_type":"congregation","content":"God upholds her for ever."},{"line_type":"leader","content":"We wait for your loving-kindness, O God, *","preface":9},{"line_type":"leader","content":"in the midst of your temple."},{"line_type":"congregation","content":"O God, according to your Name, so is your praise to the world\u2019s end; *","preface":10},{"line_type":"congregation","content":"your right hand is full of righteousness."},{"line_type":"leader","content":"Let Mount Zion rejoice, and the cities of Judah be glad, *","preface":11},{"line_type":"leader","content":"because of your judgments."},{"line_type":"congregation","content":"Walk about Zion, and go round about her; *","preface":12},{"line_type":"congregation","content":"count the number of her towers."},{"line_type":"leader","content":"Mark well her bulwarks, consider her strongholds, *","preface":13},{"line_type":"leader","content":"that you may tell those who come after."},{"line_type":"congregation","content":"This God is our God for ever and ever; *","preface":14},{"line_type":"congregation","content":"he shall be our guide, even unto death."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Judith 12"},{"line_type":"reader","content":"A reading from the Book of Judith, beginning with the twelfth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_05122b2e-b6f0-52b0-91a3-b6c874995677'></span><p><span class=\"cc vnumVis\">12</span>Then he commanded to bring her in where his plate was set; and bade that they should prepare for her of his own meats, and that she should drink of his own wine. <sup>2\u00a0</sup>And Judith said, I will not eat thereof, lest there be an offence: but provision shall be made for me of the things that I have brought. <sup>3\u00a0</sup>Then Holofernes said unto her, If thy provision should fail, how should we give thee the like? for there be none with us of thy nation. <sup>4\u00a0</sup>Then said Judith unto him As thy soul liveth, my lord, thine handmaid shall not spend those things that I have, before the Lord work by mine hand the things that he hath determined. <sup>5\u00a0</sup>Then the servants of Holofernes brought her into the tent, and she slept till midnight, and she arose when it was toward the morning watch, <sup>6\u00a0</sup>And sent to Holofernes, saving, Let my lord now command that thine handmaid may go forth unto prayer. <sup>7\u00a0</sup>Then Holofernes commanded his guard that they should not stay her: thus she abode in the camp three days, and went out in the night into the valley of Bethulia, and washed herself in a fountain of water by the camp. <sup>8\u00a0</sup>And when she came out, she besought the Lord God of Israel to direct her way to the raising up of the children of her people. <sup>9\u00a0</sup>So she came in clean, and remained in the tent, until she did eat her meat at evening. <sup>10\u00a0</sup>And in the fourth day Holofernes made a feast to his own servants only, and called none of the officers to the banquet. <sup>11\u00a0</sup>Then said he to Bagoas the eunuch, who had charge over all that he had, Go now, and persuade this Hebrew woman which is with thee, that she come unto us, and eat and drink with us. <sup>12\u00a0</sup>For, lo, it will be a shame for our person, if we shall let such a woman go, not having had her company; for if we draw her not unto us, she will laugh us to scorn. <sup>13\u00a0</sup>Then went Bagoas from the presence of Holofernes, and came to her, and he said, Let not this fair damsel fear to come to my lord, and to be honoured in his presence, and drink wine, and be merry with us and be made this day as one of the daughters of the Assyrians, which serve in the house of Nabuchodonosor. <sup>14\u00a0</sup>Then said Judith unto him, Who am I now, that I should gainsay my lord? surely whatsoever pleaseth him I will do speedily, and it shall be my joy unto the day of my death. <sup>15\u00a0</sup>So she arose, and decked herself with her apparel and all her woman\u2019s attire, and her maid went and laid soft skins on the ground for her over against Holofernes, which she had received of Bagoas far her daily use, that she might sit and eat upon them. <sup>16\u00a0</sup>Now when Judith came in and sat down, Holofernes his heart was ravished with her, and his mind was moved, and he desired greatly her company; for he waited a time to deceive her, from the day that he had seen her. <sup>17\u00a0</sup>Then said Holofernes unto her, Drink now, and be merry with us. <sup>18\u00a0</sup>So Judith said, I will drink now, my lord, because my life is magnified in me this day more than all the days since I was born. <sup>19\u00a0</sup>Then she took and ate and drank before him what her maid had prepared. <sup>20\u00a0</sup>And Holofernes took great delight in her, and drank more wine than he had drunk at any time in one day since he was born.<br/></p>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"Here ends the Reading."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"TE DEUM LAUDAMUS"},{"line_type":"subheading","content":"We Praise You, O God"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"We praise you, O God; we acclaim you as Lord; *"},{"line_type":"congregation","content":"all creation worships you, the Father everlasting."},{"line_type":"congregation","content":"To you all angels, all the powers of heaven, *"},{"line_type":"congregation","content":"the cherubim and seraphim, sing in endless praise:"},{"line_type":"congregation","content":"Holy, Holy, Holy, Lord God of power and might, *"},{"line_type":"congregation","content":"heaven and earth are full of your glory."},{"line_type":"congregation","content":"The glorious company of apostles praise you. *"},{"line_type":"congregation","content":"The noble fellowship of prophets praise you."},{"line_type":"congregation","content":"The white-robed army of martyrs praise you. *"},{"line_type":"congregation","content":"Throughout the world the holy Church acclaims you:"},{"line_type":"congregation","content":"Father, of majesty unbounded,"},{"line_type":"congregation","content":"your true and only Son, worthy of all praise, *"},{"line_type":"congregation","content":"and the Holy Spirit, advocate and guide."},{"line_type":"congregation","content":"You, Christ, are the king of glory, *"},{"line_type":"congregation","content":"the eternal Son of the Father."},{"line_type":"congregation","content":"When you took our flesh to set us free *"},{"line_type":"congregation","content":"you humbly chose the Virgin\u2019s womb."},{"line_type":"congregation","content":"You overcame the sting of death *"},{"line_type":"congregation","content":"and opened the kingdom of heaven to all believers."},{"line_type":"congregation","content":"You are seated at God\u2019s right hand in glory. *"},{"line_type":"congregation","content":"We believe that you will come to be our judge."},{"line_type":"congregation","content":"Come then, Lord, and help your people, *"},{"line_type":"congregation","content":"bought with the price of your own blood,"},{"line_type":"congregation","content":"and bring us with your saints *"},{"line_type":"congregation","content":"to glory everlasting."},{"line_type":"rubric","content":"The following verses may be omitted"},{"line_type":"congregation","content":"Save your people, Lord, and bless your inheritance;*"},{"line_type":"congregation","content":"govern and uphold them now and always."},{"line_type":"congregation","content":"Day by day we bless you; *"},{"line_type":"congregation","content":"we praise your Name for ever."},{"line_type":"congregation","content":"Keep us today, Lord, from all sin; *"},{"line_type":"congregation","content":"have mercy on us, Lord, have mercy."},{"line_type":"congregation","content":"Lord, show us your love and mercy, *"},{"line_type":"congregation","content":"for we have put our trust in you."},{"line_type":"congregation","content":"In you, Lord, is our hope; *"},{"line_type":"congregation","content":"let us never be put to shame."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Acts 17:16-34"},{"line_type":"reader","content":"A reading from the Acts of the Apostles, beginning with the seventeenth chapter, the sixteenth verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_2009b563-6136-5bde-8fc3-33e4a0c10555'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p><span class=\"text Acts-17-16\" id=\"en-AKJV-27540\"><sup class=\"versenum\">16\u00a0</sup>Now while Paul waited for them at Athens, his spirit was stirred in him, when he saw the city wholly given to idolatry. </span> <span class=\"text Acts-17-17\" id=\"en-AKJV-27541\"><sup class=\"versenum\">17\u00a0</sup>Therefore disputed he in the synagogue with the Jews, and with the devout persons, and in the market daily with them that met with him. </span> <span class=\"text Acts-17-18\" id=\"en-AKJV-27542\"><sup class=\"versenum\">18\u00a0</sup>Then certain philosophers of the Epicureans, and of the Stoicks, encountered him. And some said, What will this babbler say? other some, He seemeth to be a setter forth of strange gods: because he preached unto them Jesus, and the resurrection. </span> <span class=\"text Acts-17-19\" id=\"en-AKJV-27543\"><sup class=\"versenum\">19\u00a0</sup>And they took him, and brought him unto Areopagus, saying, May we know what this new doctrine, whereof thou speakest, is? </span> <span class=\"text Acts-17-20\" id=\"en-AKJV-27544\"><sup class=\"versenum\">20\u00a0</sup>For thou bringest certain strange things to our ears: we would know therefore what these things mean. </span> <span class=\"text Acts-17-21\" id=\"en-AKJV-27545\"><sup class=\"versenum\">21\u00a0</sup>(For all the Athenians and strangers which were there spent their time in nothing else, but either to tell, or to hear some new thing.)</span></p><span data-line-id='secondreading_d12aefd5-2e25-546f-90a3-556a6a59526e'></span> <p><span class=\"text Acts-17-22\" id=\"en-AKJV-27546\"><sup class=\"versenum\">22\u00a0</sup>Then Paul stood in the midst of Mars\u2019 hill, and said, Ye men of Athens, I perceive that in all things ye are too superstitious. </span> <span class=\"text Acts-17-23\" id=\"en-AKJV-27547\"><sup class=\"versenum\">23\u00a0</sup>For as I passed by, and beheld your devotions, I found an altar with this inscription, TO THE UNKNOWN GOD. Whom therefore ye ignorantly worship, him declare I unto you. </span> <span class=\"text Acts-17-24\" id=\"en-AKJV-27548\"><sup class=\"versenum\">24\u00a0</sup>God that made the world and all things therein, seeing that he is Lord of heaven and earth, dwelleth not in temples made with hands; </span> <span class=\"text Acts-17-25\" id=\"en-AKJV-27549\"><sup class=\"versenum\">25\u00a0</sup>neither is worshipped with men\u2019s hands, as though he needed any thing, seeing he giveth to all life, and breath, and all things; </span> <span class=\"text Acts-17-26\" id=\"en-AKJV-27550\"><sup class=\"versenum\">26\u00a0</sup>and hath made of one blood all nations of men for to dwell on all the face of the earth, and hath determined the times before appointed, and the bounds of their habitation; </span> <span class=\"text Acts-17-27\" id=\"en-AKJV-27551\"><sup class=\"versenum\">27\u00a0</sup>that they should seek the Lord, if haply they might feel after him, and find him, though he be not far from every one of us: </span> <span class=\"text Acts-17-28\" id=\"en-AKJV-27552\"><sup class=\"versenum\">28\u00a0</sup>for in him we live, and move, and have our being; as certain also of your own poets have said, For we are also his offspring. </span> <span class=\"text Acts-17-29\" id=\"en-AKJV-27553\"><sup class=\"versenum\">29\u00a0</sup>Forasmuch then as we are the offspring of God, we ought not to think that the Godhead is like unto gold, or silver, or stone, graven by art and man\u2019s device. </span> <span class=\"text Acts-17-30\" id=\"en-AKJV-27554\"><sup class=\"versenum\">30\u00a0</sup>And the times of this ignorance God winked at; but now commandeth all men every where to repent: </span> <span class=\"text Acts-17-31\" id=\"en-AKJV-27555\"><sup class=\"versenum\">31\u00a0</sup>because he hath appointed a day, in the which he will judge the world in righteousness by that man whom he hath ordained; whereof he hath given assurance unto all men, in that he hath raised him from the dead.</span></p><span data-line-id='secondreading_9a28d7bd-1eb0-5df4-957e-1234376e71f4'></span> <p><span class=\"text Acts-17-32\" id=\"en-AKJV-27556\"><sup class=\"versenum\">32\u00a0</sup>And when they heard of the resurrection of the dead, some mocked: and others said, We will hear thee again of this matter. </span> <span class=\"text Acts-17-33\" id=\"en-AKJV-27557\"><sup class=\"versenum\">33\u00a0</sup>So Paul departed from among them. </span> <span class=\"text Acts-17-34\" id=\"en-AKJV-27558\"><sup class=\"versenum\">34\u00a0</sup>Howbeit certain men clave unto him, and believed: among the which was Dionysius the Areopagite, and a woman named Damaris, and others with them.</span></p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"BENEDICTUS"},{"line_type":"subheading","content":"The Song of Zechariah"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Blessed be the Lord, the God of Israel; *"},{"line_type":"congregation","content":"he has come to his people and set them free."},{"line_type":"congregation","content":"He has raised up for us a mighty savior, *"},{"line_type":"congregation","content":"born of the house of his servant David."},{"line_type":"congregation","content":"Through his holy prophets he promised of old"},{"line_type":"congregation","content":"that he would save us from our enemies, *"},{"line_type":"congregation","content":"from the hands of all who hate us."},{"line_type":"congregation","content":"He promised to show mercy to our fathers *"},{"line_type":"congregation","content":"and to remember his holy covenant."},{"line_type":"congregation","content":"This was the oath he swore to our father Abraham, *"},{"line_type":"congregation","content":"to set us free from the hands of our enemies,"},{"line_type":"congregation","content":"Free to worship him without fear, *"},{"line_type":"congregation","content":"holy and righteous in his sight"},{"line_type":"congregation","content":"all the days of our life."},{"line_type":"congregation","content":"You, my child, shall be called the prophet of the Most High, *"},{"line_type":"congregation","content":"for you will go before the Lord to prepare his way,"},{"line_type":"congregation","content":"To give his people knowledge of salvation *"},{"line_type":"congregation","content":"by the forgiveness of their sins."},{"line_type":"congregation","content":"In the tender compassion of our God *"},{"line_type":"congregation","content":"the dawn from on high shall break upon us,"},{"line_type":"congregation","content":"To shine on those who dwell in darkness"},{"line_type":"congregation","content":"and in the shadow of death, *"},{"line_type":"congregation","content":"and to guide our feet into the way of peace."},{"line_type":"citation","content":"LUKE 1:68-79"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"O Lord, show your mercy upon us;"},{"line_type":"congregation_dialogue","content":"And grant us your salvation."},{"line_type":"leader_dialogue","content":"O Lord, guide those who govern us"},{"line_type":"congregation_dialogue","content":"And lead us in the way of justice and truth."},{"line_type":"leader_dialogue","content":"Clothe your ministers with righteousness"},{"line_type":"congregation_dialogue","content":"And let your people sing with joy."},{"line_type":"leader_dialogue","content":"O Lord, save your people"},{"line_type":"congregation_dialogue","content":"And bless your inheritance."},{"line_type":"leader_dialogue","content":"Give peace in our time, O Lord"},{"line_type":"congregation_dialogue","content":"And defend us by your mighty power."},{"line_type":"leader_dialogue","content":"Let not the needy, O Lord, be forgotten"},{"line_type":"congregation_dialogue","content":"Nor the hope of the poor be taken away."},{"line_type":"leader_dialogue","content":"Create in us clean hearts, O God"},{"line_type":"congregation_dialogue","content":"And take not your Holy Spirit from us."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Wednesday after the Twenty-fifth Sunday after Pentecost, or the Twenty-fourth Sunday after Trinity (Proper 28)"},{"line_type":"leader","content":"Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Elizabeth of Hungary, Renewer of Society, 1231"},{"line_type":"leader","content":"Almighty and everlasting God, you kindled the flame of your love in the heart of your servant Elizabeth of Hungary to manifest your compassion and mercy to the poor and the persecuted: Grant to us, your humble servants, a like faith and power of love, that we who give thanks for her righteous zeal may profit by her example; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for Grace"},{"line_type":"subheading","content":"Wednesday"},{"line_type":"leader","content":"O Lord, our heavenly Father, almighty and everlasting God, you have brought us safely to the beginning of this day: Defend us by your mighty power, that we may not fall into sin nor run into any danger; and that, guided by your Spirit, we may do what is righteous in your sight; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"Lord Jesus Christ, you stretched out your arms of love on the hard wood of the Cross that everyone might come within the reach of your saving embrace: So clothe us in your Spirit that we, reaching forth our hands in love, may bring those who do not know you to the knowledge and love of you; for the honor of your Name."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit, be with us all evermore."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"2 CORINTHIANS 13:14"}]}],"midday_prayer":[{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 119:105-112"},{"line_type":"subheading","content":"Beati immaculati"},{"line_type":"leader","content":"Your word is a lantern to my feet *","preface":105},{"line_type":"leader","content":"and a light upon my path."},{"line_type":"congregation","content":"I have sworn and am steadfastly purposed *","preface":106},{"line_type":"congregation","content":"to keep your righteous judgments."},{"line_type":"leader","content":"I am troubled above measure; *","preface":107},{"line_type":"leader","content":"revive me, O L\u1d0f\u0280\u1d05, according to your word."},{"line_type":"congregation","content":"Let the freewill offerings of my mouth please you, O L\u1d0f\u0280\u1d05; *","preface":108},{"line_type":"congregation","content":"and teach me your judgments."},{"line_type":"leader","content":"My life is always in my hand, *","preface":109},{"line_type":"leader","content":"yet I do not forget your law."},{"line_type":"congregation","content":"The ungodly have laid a snare for me, *","preface":110},{"line_type":"congregation","content":"yet I have not strayed from your commandments."},{"line_type":"leader","content":"Your testimonies have I claimed as my heritage for ever, *","preface":111},{"line_type":"leader","content":"and why? They are the very joy of my heart."},{"line_type":"congregation","content":"I have applied my heart to fulfill your statutes always, *","preface":112},{"line_type":"congregation","content":"even unto the end. Samekh"},{"line_type":"heading","content":"Psalm 121"},{"line_type":"subheading","content":"Levavi oculos"},{"line_type":"leader","content":"I will lift up my eyes unto the hills; *","preface":1},{"line_type":"leader","content":"from whence comes my help?"},{"line_type":"congregation","content":"My help comes from the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"who has made heaven and earth."},{"line_type":"leader","content":"He will not let your foot be moved, *","preface":3},{"line_type":"leader","content":"and he who keeps you will not sleep."},{"line_type":"congregation","content":"Behold, he who keeps Israel *","preface":4},{"line_type":"congregation","content":"shall neither slumber nor sleep."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 himself is your keeper; *","preface":5},{"line_type":"leader","content":"the L\u1d0f\u0280\u1d05 is your defense upon your right hand,"},{"line_type":"congregation","content":"So that the sun shall not burn you by day, *","preface":6},{"line_type":"congregation","content":"neither the moon by night."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 shall preserve you from all evil; *","preface":7},{"line_type":"leader","content":"indeed, it is he who shall keep your soul."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 shall preserve your going out and your coming in, *","preface":8},{"line_type":"congregation","content":"from this time forth for evermore."},{"line_type":"heading","content":"Psalm 124"},{"line_type":"subheading","content":"Nisi quia Dominus"},{"line_type":"leader","content":"If the L\u1d0f\u0280\u1d05 himself had not been on our side, now may Israel say: *","preface":1},{"line_type":"leader","content":"if the L\u1d0f\u0280\u1d05 himself had not been on our side, when men rose up against us,"},{"line_type":"congregation","content":"Then would they have swallowed us up alive, *","preface":2},{"line_type":"congregation","content":"when they were so wrathfully displeased with us;"},{"line_type":"leader","content":"Then the waters would have drowned us, and the torrent gone over us; *","preface":3},{"line_type":"leader","content":"then the raging waters would have gone clean over us."},{"line_type":"congregation","content":"But praised be the L\u1d0f\u0280\u1d05, *","preface":4},{"line_type":"congregation","content":"who has not given us over to be prey for their teeth."},{"line_type":"leader","content":"We escaped like a bird out of the snare of the fowler; *","preface":5},{"line_type":"leader","content":"the snare is broken, and we have been delivered."},{"line_type":"congregation","content":"Our help is in the Name of the L\u1d0f\u0280\u1d05, *","preface":6},{"line_type":"congregation","content":"the maker of heaven and earth."},{"line_type":"heading","content":"Psalm 126"},{"line_type":"subheading","content":"In convertendo"},{"line_type":"leader","content":"When the L\u1d0f\u0280\u1d05 overturned the captivity of Zion, *","preface":1},{"line_type":"leader","content":"then were we like those who dream."},{"line_type":"congregation","content":"Then was our mouth filled with laughter *","preface":2},{"line_type":"congregation","content":"and our tongue with shouts of joy."},{"line_type":"leader","content":"Then they said among the nations, *","preface":3},{"line_type":"leader","content":"\u201cThe L\u1d0f\u0280\u1d05 has done great things for them.\u201d"},{"line_type":"congregation","content":"Indeed, the L\u1d0f\u0280\u1d05 has done great things for us already, *","preface":4},{"line_type":"congregation","content":"whereof we rejoice."},{"line_type":"leader","content":"Overturn our captivity, O L\u1d0f\u0280\u1d05, *","preface":5},{"line_type":"leader","content":"as when streams refresh the deserts of the south."},{"line_type":"congregation","content":"Those who sow in tears *","preface":6},{"line_type":"congregation","content":"shall reap with songs of joy."},{"line_type":"leader","content":"He who goes on his way weeping and bears good seed *","preface":7},{"line_type":"leader","content":"shall doubtless come again with joy, and bring his sheaves with him."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"From the rising of the sun to its setting my name will be great among the nations, and in every place incense will be offered to my name, and a pure offering. For my name will be great among the nations, says the Lord of Hosts."},{"line_type":"citation","content":"MALACHI 1:11"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"A meditation, silent or spoken, may follow."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"I will bless the Lord at all times."},{"line_type":"congregation_dialogue","content":"His praise shall continually be in my mouth."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Blessed Savior, at this hour you hung upon the Cross, stretching out your loving arms: Grant that all the peoples of the earth may look to you and be saved; for your tender mercies\u2019 sake."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Father of all mercies, you revealed your boundless compassion to your apostle Saint Peter in a three-fold vision: Forgive our unbelief, we pray, and so strengthen our hearts and enkindle our zeal, that we may fervently desire the salvation of all people, and diligently labor in the extension of your kingdom; through him who gave himself for the life of the world, your Son our Savior Jesus Christ."},{"line_type":"congregation","content":"Amen."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader","content":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit, be with us all evermore."},{"line_type":"congregation","content":"Amen."}]}],"evening_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"Let my prayer be set forth in your sight as incense, and let the lifting up of my hands be an evening sacrifice."},{"line_type":"citation","content":"PSALM 141:2"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Let us humbly confess our sins to Almighty God."},{"line_type":"rubric","content":"Silence is kept. All kneeling, the Officiant and People say"},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"PHOS HILARON"},{"line_type":"subheading","content":"O Gladsome Light"},{"line_type":"congregation","content":"O gladsome light,"},{"line_type":"congregation","content":"pure brightness of the everliving Father in heaven, *"},{"line_type":"congregation","content":"O Jesus Christ, holy and blessed!"},{"line_type":"congregation","content":"Now as we come to the setting of the sun,"},{"line_type":"congregation","content":"and our eyes behold the vesper light, *"},{"line_type":"congregation","content":"we sing your praises, O God: Father, Son, and Holy Spirit."},{"line_type":"congregation","content":"You are worthy at all times to be praised by happy voices, *"},{"line_type":"congregation","content":"O Son of God, O Giver of Life,"},{"line_type":"congregation","content":"and to be glorified through all the worlds."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalm Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 49"},{"line_type":"subheading","content":"Audite h\u00e6c, omnes"},{"line_type":"leader","content":"Hear this, all you peoples; *","preface":1},{"line_type":"leader","content":"ponder it with your ears, all who dwell in the world,"},{"line_type":"congregation","content":"High and low, rich and poor, *","preface":2},{"line_type":"congregation","content":"everyone with his neighbor."},{"line_type":"leader","content":"My mouth shall speak of wisdom, *","preface":3},{"line_type":"leader","content":"and my heart shall muse on understanding."},{"line_type":"congregation","content":"I will incline my ear to a parable, *","preface":4},{"line_type":"congregation","content":"and declare my dark sayings with the harp."},{"line_type":"leader","content":"Why should I fear in the days of wickedness, *","preface":5},{"line_type":"leader","content":"and when the wicked at my heels encompass me round about?"},{"line_type":"congregation","content":"There are some who put their trust in their goods, *","preface":6},{"line_type":"congregation","content":"and boast in the multitude of their riches."},{"line_type":"leader","content":"But no one can deliver his brother, *","preface":7},{"line_type":"leader","content":"nor pay unto God a price for him;"},{"line_type":"congregation","content":"For it is so costly to redeem their souls, *","preface":8},{"line_type":"congregation","content":"that we should never have enough to pay it,"},{"line_type":"leader","content":"So that they should live for ever, *","preface":9},{"line_type":"leader","content":"and should not see the grave."},{"line_type":"congregation","content":"For we see that wise men die, as well as the ignorant and foolish; *","preface":10},{"line_type":"congregation","content":"they perish alike and leave their riches for others."},{"line_type":"leader","content":"And yet they think that their houses shall continue for ever, and that their dwelling places shall endure from one generation to another, *","preface":11},{"line_type":"leader","content":"and they call lands after their own names."},{"line_type":"congregation","content":"Man is like an ox that has no understanding; *","preface":12},{"line_type":"congregation","content":"he is like the beasts that perish."},{"line_type":"leader","content":"This is the way of their foolishness, *","preface":13},{"line_type":"leader","content":"yet their posterity praise their sayings."},{"line_type":"congregation","content":"Like sheep they are appointed to die, and death shall be their shepherd; *","preface":14},{"line_type":"congregation","content":"they shall go down straight into the sepulcher."},{"line_type":"leader","content":"Their beauty shall consume away in the grave, *","preface":15},{"line_type":"leader","content":"which shall be their dwelling place for ever."},{"line_type":"congregation","content":"But God shall save me from the power of death, *","preface":16},{"line_type":"congregation","content":"for he shall deliver my soul."},{"line_type":"leader","content":"Be not envious if one is made rich, *","preface":17},{"line_type":"leader","content":"or if the glory of his house is increased,"},{"line_type":"congregation","content":"For he shall carry nothing away with him when he dies, *","preface":18},{"line_type":"congregation","content":"neither shall his glory follow him."},{"line_type":"leader","content":"For while he lived, he counted himself happy, *","preface":19},{"line_type":"leader","content":"and so long as he did well for himself, people spoke well of him."},{"line_type":"congregation","content":"He shall follow the generation of his fathers *","preface":20},{"line_type":"congregation","content":"and shall never see the light."},{"line_type":"leader","content":"Those who are honored but have no understanding *","preface":21},{"line_type":"leader","content":"are like the beasts that perish."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Isaiah 31"},{"line_type":"reader","content":"A reading from the Prophet Isaiah, beginning with the thirty-first chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_1e70bcae-0973-5da9-8c93-169234df4259'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<div class=\"poetry top-1\"><p class=\"line\"><span class=\"chapter-2\"><span class=\"text Isa-31-1\" id=\"en-AKJV-18252\"><span class=\"chapternum\">31\u00a0</span>Woe to them that go down to Egypt for help;</span></span><br/><span class=\"text Isa-31-1\">and stay on horses, and trust in chariots, because they are many;</span><br/><span class=\"text Isa-31-1\">and in horsemen, because they are very strong;</span><br/><span class=\"text Isa-31-1\">but they look not unto the Holy One of Israel,</span><br/><span class=\"text Isa-31-1\">neither seek the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>!</span><br/><span class=\"text Isa-31-2\" id=\"en-AKJV-18253\"><sup class=\"versenum\">2\u00a0</sup>Yet he also is wise, and will bring evil,</span><br/><span class=\"text Isa-31-2\">and will not call back his words:</span><br/><span class=\"text Isa-31-2\">but will arise against the house of the evildoers,</span><br/><span class=\"text Isa-31-2\">and against the help of them that work iniquity.</span><br/><span class=\"text Isa-31-3\" id=\"en-AKJV-18254\"><sup class=\"versenum\">3\u00a0</sup>Now the Egyptians are men, and not God;</span><br/><span class=\"text Isa-31-3\">and their horses flesh, and not spirit.</span><br/><span class=\"text Isa-31-3\">When the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> shall stretch out his hand,</span><br/><span class=\"text Isa-31-3\">both he that helpeth shall fall,</span><br/><span class=\"text Isa-31-3\">and he that is holpen shall fall down,</span><br/><span class=\"text Isa-31-3\">and they all shall fail together.</span></p><span data-line-id='firstreading_a896ff10-1321-5cce-86fd-1a9a65ba2585'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-31-4\" id=\"en-AKJV-18255\"><sup class=\"versenum\">4\u00a0</sup>For thus hath the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> spoken unto me,</span><br/><span class=\"text Isa-31-4\">Like as the lion and the young lion roaring on his prey,</span><br/><span class=\"text Isa-31-4\">when a multitude of shepherds is called forth against him,</span><br/><span class=\"text Isa-31-4\">he will not be afraid of their voice,</span><br/><span class=\"text Isa-31-4\">nor abase himself for the noise of them:</span><br/><span class=\"text Isa-31-4\">so shall the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> of hosts come down to fight</span><br/><span class=\"text Isa-31-4\">for mount Zion, and for the hill thereof.</span><br/><span class=\"text Isa-31-5\" id=\"en-AKJV-18256\"><sup class=\"versenum\">5\u00a0</sup>As birds flying, so will the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> of hosts defend Jerusalem;</span><br/><span class=\"text Isa-31-5\">defending also he will deliver it;</span><br/><span class=\"text Isa-31-5\">and passing over he will preserve it.</span></p><span data-line-id='firstreading_0fa5f1aa-f2b0-56bb-86f1-7593cf7d27ca'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-31-6\" id=\"en-AKJV-18257\"><sup class=\"versenum\">6\u00a0</sup>Turn ye unto him from whom the children of Israel have deeply revolted.</span><br/><span class=\"text Isa-31-7\" id=\"en-AKJV-18258\"><sup class=\"versenum\">7\u00a0</sup>For in that day every man shall cast away</span><br/><span class=\"text Isa-31-7\">his idols of silver, and his idols of gold,</span><br/><span class=\"text Isa-31-7\">which your own hands have made unto you for a sin.</span></p><span data-line-id='firstreading_f8218af8-3960-5e37-b992-60da59848f38'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-31-8\" id=\"en-AKJV-18259\"><sup class=\"versenum\">8\u00a0</sup>Then shall the Assyrian fall with the sword, not of a mighty man;</span><br/><span class=\"text Isa-31-8\">and the sword, not of a mean man, shall devour him:</span><br/><span class=\"text Isa-31-8\">but he shall flee from the sword,</span><br/><span class=\"text Isa-31-8\">and his young men shall be discomfited.</span><br/><span class=\"text Isa-31-9\" id=\"en-AKJV-18260\"><sup class=\"versenum\">9\u00a0</sup>And he shall pass over to his strong hold for fear,</span><br/><span class=\"text Isa-31-9\">and his princes shall be afraid of the ensign,</span><br/><span class=\"text Isa-31-9\">saith the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>, whose fire is in Zion,</span><br/><span class=\"text Isa-31-9\">and his furnace in Jerusalem.</span></p></div> </div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"MAGNIFICAT"},{"line_type":"subheading","content":"The Song of Mary"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"My soul magnifies the Lord, *"},{"line_type":"congregation","content":"and my spirit rejoices in God my Savior;"},{"line_type":"congregation","content":"For he has regarded *"},{"line_type":"congregation","content":"the lowliness of his handmaiden."},{"line_type":"congregation","content":"For behold, from now on, *"},{"line_type":"congregation","content":"all generations will call me blessed;"},{"line_type":"congregation","content":"For he that is mighty has magnified me, *"},{"line_type":"congregation","content":"and holy is his Name."},{"line_type":"congregation","content":"And his mercy is on those who fear him, *"},{"line_type":"congregation","content":"throughout all generations."},{"line_type":"congregation","content":"He has shown the strength of his arm; *"},{"line_type":"congregation","content":"he has scattered the proud in the imagination of their hearts."},{"line_type":"congregation","content":"He has brought down the mighty from their thrones, *"},{"line_type":"congregation","content":"and has exalted the humble and meek."},{"line_type":"congregation","content":"He has filled the hungry with good things, *"},{"line_type":"congregation","content":"and the rich he has sent empty away."},{"line_type":"congregation","content":"He, remembering his mercy, has helped his servant Israel, *"},{"line_type":"congregation","content":"as he promised to our fathers, Abraham and his seed for ever."},{"line_type":"citation","content":"LUKE 1:46-55"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Luke 3:23-38"},{"line_type":"reader","content":"A reading from the Gospel of our Lord Jesus Christ according to St. Luke, beginning with the third chapter, the twenty-third verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_0206b9ef-b18d-5698-8c92-e60bebdaeead'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p><span class=\"text Luke-3-23\" id=\"en-AKJV-25049\"><sup class=\"versenum\">23\u00a0</sup>And Jesus himself began to be about thirty years of age, being (as was supposed) the son of Joseph, which was the son of Heli, </span> <span class=\"text Luke-3-24\" id=\"en-AKJV-25050\"><sup class=\"versenum\">24\u00a0</sup>which was the son of Matthat, which was the son of Levi, which was the son of Melchi, which was the son of Janna, which was the son of Joseph, </span> <span class=\"text Luke-3-25\" id=\"en-AKJV-25051\"><sup class=\"versenum\">25\u00a0</sup>which was the son of Mattathias, which was the son of Amos, which was the son of Naum, which was the son of Esli, which was the son of Nagge, </span> <span class=\"text Luke-3-26\" id=\"en-AKJV-25052\"><sup class=\"versenum\">26\u00a0</sup>which was the son of Maath, which was the son of Mattathias, which was the son of Semei, which was the son of Joseph, which was the son of Juda, </span> <span class=\"text Luke-3-27\" id=\"en-AKJV-25053\"><sup class=\"versenum\">27\u00a0</sup>which was the son of Joanna, which was the son of Rhesa, which was the son of Zorobabel, which was the son of Salathiel, which was the son of Neri, </span> <span class=\"text Luke-3-28\" id=\"en-AKJV-25054\"><sup class=\"versenum\">28\u00a0</sup>which was the son of Melchi, which was the son of Addi, which was the son of Cosam, which was the son of Elmodam, which was the son of Er, </span> <span class=\"text Luke-3-29\" id=\"en-AKJV-25055\"><sup class=\"versenum\">29\u00a0</sup>which was the son of Jose, which was the son of Eliezer, which was the son of Jorim, which was the son of Matthat, which was the son of Levi, </span> <span class=\"text Luke-3-30\" id=\"en-AKJV-25056\"><sup class=\"versenum\">30\u00a0</sup>which was the son of Simeon, which was the son of Juda, which was the son of Joseph, which was the son of Jonan, which was the son of Eliakim, </span> <span class=\"text Luke-3-31\" id=\"en-AKJV-25057\"><sup class=\"versenum\">31\u00a0</sup>which was the son of Melea, which was the son of Menan, which was the son of Mattatha, which was the son of Nathan, which was the son of David, </span> <span class=\"text Luke-3-32\" id=\"en-AKJV-25058\"><sup class=\"versenum\">32\u00a0</sup>which was the son of Jesse, which was the son of Obed, which was the son of Booz, which was the son of Salmon, which was the son of Naasson, </span> <span class=\"text Luke-3-33\" id=\"en-AKJV-25059\"><sup class=\"versenum\">33\u00a0</sup>which was the son of Aminadab, which was the son of Aram, which was the son of Esrom, which was the son of Phares, which was the son of Juda, </span> <span class=\"text Luke-3-34\" id=\"en-AKJV-25060\"><sup class=\"versenum\">34\u00a0</sup>which was the son of Jacob, which was the son of Isaac, which was the son of Abraham, which was the son of Thara, which was the son of Nachor, </span> <span class=\"text Luke-3-35\" id=\"en-AKJV-25061\"><sup class=\"versenum\">35\u00a0</sup>which was the son of Saruch, which was the son of Ragau, which was the son of Phalec, which was the son of Heber, which was the son of Sala, </span> <span class=\"text Luke-3-36\" id=\"en-AKJV-25062\"><sup class=\"versenum\">36\u00a0</sup>which was the son of Cainan, which was the son of Arphaxad, which was the son of Sem, which was the son of Noe, which was the son of Lamech, </span> <span class=\"text Luke-3-37\" id=\"en-AKJV-25063\"><sup class=\"versenum\">37\u00a0</sup>which was the son of Mathusala, which was the son of Enoch, which was the son of Jared, which was the son of Maleleel, which was the son of Cainan, </span> <span class=\"text Luke-3-38\" id=\"en-AKJV-25064\"><sup class=\"versenum\">38\u00a0</sup>which was the son of Enos, which was the son of Seth, which was the son of Adam, which was the son of God.</span></p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"NUNC DIMITTIS"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"citation","content":"LUKE 2:29-32"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"O Lord, show your mercy upon us;"},{"line_type":"congregation_dialogue","content":"And grant us your salvation."},{"line_type":"leader_dialogue","content":"O Lord, guide those who govern us"},{"line_type":"congregation_dialogue","content":"And lead us in the way of justice and truth."},{"line_type":"leader_dialogue","content":"Clothe your ministers with righteousness"},{"line_type":"congregation_dialogue","content":"And let your people sing with joy."},{"line_type":"leader_dialogue","content":"O Lord, save your people"},{"line_type":"congregation_dialogue","content":"And bless your inheritance."},{"line_type":"leader_dialogue","content":"Give peace in our time, O Lord"},{"line_type":"congregation_dialogue","content":"And defend us by your mighty power."},{"line_type":"leader_dialogue","content":"Let not the needy, O Lord, be forgotten"},{"line_type":"congregation_dialogue","content":"Nor the hope of the poor be taken away."},{"line_type":"leader_dialogue","content":"Create in us clean hearts, O God"},{"line_type":"congregation_dialogue","content":"And take not your Holy Spirit from us."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Wednesday after the Twenty-fifth Sunday after Pentecost, or the Twenty-fourth Sunday after Trinity (Proper 28)"},{"line_type":"leader","content":"Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Elizabeth of Hungary, Renewer of Society, 1231"},{"line_type":"leader","content":"Almighty and everlasting God, you kindled the flame of your love in the heart of your servant Elizabeth of Hungary to manifest your compassion and mercy to the poor and the persecuted: Grant to us, your humble servants, a like faith and power of love, that we who give thanks for her righteous zeal may profit by her example; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for Protection"},{"line_type":"subheading","content":"Wednesday"},{"line_type":"leader","content":"O God, the life of all who live, the light of the faithful, the strength of those who labor, and the repose of the dead: We thank you for the blessings of the day that is past, and humbly ask for your protection through the coming night. Bring us in safety to the morning hours; through him who died and rose again for us, your Son our Savior Jesus Christ."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"Keep watch, dear Lord, with those who work, or watch, or weep this night, and give your angels charge over those who sleep. Tend the sick, Lord Christ; give rest to the weary, bless the dying, soothe the suffering, pity the afflicted, shield the joyous; and all for your love's sake."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit, be with us all evermore."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"2 CORINTHIANS 13:14"}]}],"compline":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"rubric","content":"The Officiant begins:"},{"line_type":"leader_dialogue","content":"The Lord Almighty grant us a peaceful night and a perfect end."},{"line_type":"congregation_dialogue","content":"Amen."},{"line_type":"leader_dialogue","content":"Our help is in the Name of the Lord;"},{"line_type":"congregation_dialogue","content":"The maker of heaven and earth."}]},{"name":"Confession","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant continues"},{"line_type":"leader_dialogue","content":"Let us humbly confess our sins unto Almighty God."},{"line_type":"rubric","content":"Silence may be kept. The Officiant and People then say"},{"line_type":"congregation","content":"Almighty God and Father, we confess to you,"},{"line_type":"congregation","content":"to one another, and to the whole company of heaven,"},{"line_type":"congregation","content":"that we have sinned, through our own fault,"},{"line_type":"congregation","content":"in thought, and word, and deed, and in what we have left undone."},{"line_type":"congregation","content":"For the sake of your Son our Lord Jesus Christ,"},{"line_type":"congregation","content":"have mercy upon us, forgive us our sins,"},{"line_type":"congregation","content":"and by the power of your Holy Spirit,"},{"line_type":"congregation","content":"raise us up to serve you in newness of life,"},{"line_type":"congregation","content":"to the glory of your Name. Amen."},{"line_type":"rubric","content":"The Officiant alone says"},{"line_type":"leader","content":"May almighty God grant us forgiveness of all our sins, and the grace and comfort of the Holy Spirit."},{"line_type":"congregation","content":"Amen."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 4"},{"line_type":"subheading","content":"Cum invocarem"},{"line_type":"leader","content":"Hear me when I call, O God of my righteousness; *","preface":1},{"line_type":"leader","content":"you set me free when I was in trouble; have mercy upon me, and hear my prayer."},{"line_type":"congregation","content":"O you children of men, how long will you blaspheme my honor, *","preface":2},{"line_type":"congregation","content":"and have such pleasure in vanity, and seek after falsehood?"},{"line_type":"leader","content":"Know this also, that the L\u1d0f\u0280\u1d05 has chosen for himself the one that is godly; *","preface":3},{"line_type":"leader","content":"when I call upon the L\u1d0f\u0280\u1d05, he will hear me."},{"line_type":"congregation","content":"Stand in awe, and sin not; *","preface":4},{"line_type":"congregation","content":"commune with your own heart upon your bed, and be still."},{"line_type":"leader","content":"Offer the sacrifice of righteousness *","preface":5},{"line_type":"leader","content":"and put your trust in the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"There are many that say, \u201cWho will show us any good?\u201d *","preface":6},{"line_type":"congregation","content":"L\u1d0f\u0280\u1d05, lift up the light of your countenance upon us."},{"line_type":"leader","content":"You have put gladness in my heart, *","preface":7},{"line_type":"leader","content":"more than when others\u2019 grain and wine and oil increased."},{"line_type":"congregation","content":"I will lay me down in peace, and take my rest; *","preface":8},{"line_type":"congregation","content":"for you, L\u1d0f\u0280\u1d05, only, make me dwell in safety."},{"line_type":"heading","content":"Psalm 31:1-6"},{"line_type":"subheading","content":"In te, Domine, speravi"},{"line_type":"leader","content":"In you, O L\u1d0f\u0280\u1d05, have I put my trust; *","preface":1},{"line_type":"leader","content":"let me never be put to confusion; deliver me in your righteousness."},{"line_type":"congregation","content":"Bow down your ear to me, *","preface":2},{"line_type":"congregation","content":"make haste to deliver me,"},{"line_type":"leader","content":"And be my strong rock and house of defense, *","preface":3},{"line_type":"leader","content":"that you may save me."},{"line_type":"congregation","content":"For you are my strong rock and my castle; *","preface":4},{"line_type":"congregation","content":"be also my guide, and lead me for your Name\u2019s sake."},{"line_type":"leader","content":"Draw me out of the net that they have laid secretly for me, *","preface":5},{"line_type":"leader","content":"for you are my strength."},{"line_type":"congregation","content":"Into your hands I commend my spirit, *","preface":6},{"line_type":"congregation","content":"for you have redeemed me, O L\u1d0f\u0280\u1d05, O God of truth."},{"line_type":"heading","content":"Psalm 91"},{"line_type":"subheading","content":"Qui habitat"},{"line_type":"leader","content":"Whoever dwells under the defense of the Most High *","preface":1},{"line_type":"leader","content":"shall abide under the shadow of the Almighty."},{"line_type":"congregation","content":"I will say unto the L\u1d0f\u0280\u1d05, \u201cYou are my refuge and my stronghold, *","preface":2},{"line_type":"congregation","content":"my God in whom I will trust.\u201d"},{"line_type":"leader","content":"For he shall deliver you from the snare of the hunter *","preface":3},{"line_type":"leader","content":"and from the deadly pestilence."},{"line_type":"congregation","content":"He shall defend you under his wings, and you shall be safe under his feathers; *","preface":4},{"line_type":"congregation","content":"his faithfulness and truth shall be your shield and buckler."},{"line_type":"leader","content":"You shall not be afraid of any terror by night, *","preface":5},{"line_type":"leader","content":"nor of the arrow that flies by day,"},{"line_type":"congregation","content":"Of the pestilence that walks in darkness, *","preface":6},{"line_type":"congregation","content":"nor of the sickness that destroys at noonday."},{"line_type":"leader","content":"A thousand shall fall beside you, and ten thousand at your right hand, *","preface":7},{"line_type":"leader","content":"but it shall not come near you."},{"line_type":"congregation","content":"Indeed, with your eyes you shall behold *","preface":8},{"line_type":"congregation","content":"and see the reward of the ungodly."},{"line_type":"leader","content":"Because you have said, \u201cThe L\u1d0f\u0280\u1d05 is my refuge,\u201d *","preface":9},{"line_type":"leader","content":"and have made the Most High your stronghold,"},{"line_type":"congregation","content":"There shall no evil happen to you, *","preface":10},{"line_type":"congregation","content":"neither shall any plague come near your dwelling."},{"line_type":"leader","content":"For he shall give his angels charge over you, *","preface":11},{"line_type":"leader","content":"to keep you in all your ways."},{"line_type":"congregation","content":"They shall bear you in their hands, *","preface":12},{"line_type":"congregation","content":"that you hurt not your foot against a stone."},{"line_type":"leader","content":"You shall tread upon the lion and adder; *","preface":13},{"line_type":"leader","content":"the young lion and the serpent you shall trample under your feet."},{"line_type":"congregation","content":"\u201cBecause he has set his love upon me, therefore I will deliver him; *","preface":14},{"line_type":"congregation","content":"I will lift him up, because he has known my Name."},{"line_type":"leader","content":"He shall call upon me, and I will hear him; *","preface":15},{"line_type":"leader","content":"indeed, I am with him in trouble; I will deliver him and bring him honor."},{"line_type":"congregation","content":"With long life I will satisfy him, *","preface":16},{"line_type":"congregation","content":"and show him my salvation.\u201d"},{"line_type":"heading","content":"Psalm 134"},{"line_type":"subheading","content":"Ecce nunc"},{"line_type":"leader","content":"Behold now, praise the L\u1d0f\u0280\u1d05, *","preface":1},{"line_type":"leader","content":"all you servants of the L\u1d0f\u0280\u1d05,"},{"line_type":"congregation","content":"You that stand by night in the house of the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"even in the courts of the house of our God."},{"line_type":"leader","content":"Lift up your hands in the sanctuary *","preface":3},{"line_type":"leader","content":"and sing praises unto the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 who made heaven and earth *","preface":4},{"line_type":"congregation","content":"give you blessing out of Zion."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"Now may the God of peace who brought again from the dead our Lord Jesus, the great shepherd of the sheep, by the blood of the eternal covenant, equip you with everything good that you may do his will, working in us that which is pleasing in his sight, through Jesus Christ, to whom be glory forever and ever. Amen."},{"line_type":"citation","content":"HEBREWS 13:20-21"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"Into your hands, O Lord, I commend my spirit;"},{"line_type":"congregation_dialogue","content":"For you have redeemed me, O Lord, O God of truth."},{"line_type":"leader_dialogue","content":"Keep me, O Lord, as the apple of your eye;"},{"line_type":"congregation_dialogue","content":"Hide me under the shadow of your wings."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Aid Against Peril"},{"line_type":"leader","content":"Lighten our darkness, we beseech you, O Lord; and by your great mercy defend us from all perils and dangers of this night; for the love of your only Son, our Savior Jesus Christ."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"Look down, O Lord, from your heavenly throne, illumine this night with your celestial brightness, and from the children of light banish the deeds of darkness; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"O God, your unfailing providence sustains the world we live in and the life we live: Watch over those, both night and day, who work while others sleep, and grant that we may never forget that our common life depends upon each other\u2019s toil; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Nunc Dimittis","lines":[{"line_type":"heading","content":"Nunc Dimittis"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The Officiant and People say or sing the Song of Simeon with this Antiphon, all standing"},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader_dialogue","content":"The almighty and merciful Lord, Father, Son, and Holy Spirit, bless us and keep us, this night and evermore."},{"line_type":"congregation_dialogue","content":"Amen."}]}]}};
